def compare_systems(rows):
    """Baseline vs system correctness counts from (baseline_ok, system_ok) rows."""
    clean = []
    for row in rows:
        if len(row) != 2:
            raise ValueError("jede Zeile braucht zwei Eintraege")
        clean.append((bool(row[0]), bool(row[1])))
    n = len(clean)
    base = sum(1 for b, s in clean if b)
    system = sum(1 for b, s in clean if s)
    delta = system - base
    relative = 0 if base == 0 else int(round(100.0 * delta / base))
    return {"n": n, "baseline_correct": base, "system_correct": system,
            "delta_correct": delta, "relative_percent": relative}

