def recall(gesamt, getroffen):
    if not gesamt:
        return 0.0
    return getroffen / gesamt

gruppen = {
    "versand": (2, 2),
    "recht": (2, 1),
    "rabatt": (2, 1),
    "garantie": (2, 2),
}
werte = {name: recall(g, t) for name, (g, t) in gruppen.items()}
print(werte["versand"], werte["rabatt"])
print(round(100 * sum(werte.values()) / len(werte), 1))

